messages:
AC1  NA revenue missed plan by 4%
     check=revenue_vs_plan params={"segment": "_all_", "target_pct": 96, "band_pct": 2}
AC2  Enterprise drove the miss (depends_on: AC1)
     check=revenue_vs_plan params={"segment": "Enterprise", "target_pct": 93, "band_pct": 2}
AC3  Headline coverage ~3.4x
     check=coverage_ratio params={"quarter": "FY26-Q1", "min_multiple": 3.4}
AC4  Pipeline concentrated in lower-potential territories
     check=potential_coverage_gap params={"dimension": "territory", "min_gap_pp": 15}
AC5  Pipeline skewed toward early-stage deals
     check=stage_aging params={"stale_threshold_days": 90, "max_stale_share_pct": 40}
AC6  Close dates slipping into later quarters
     check=slippage_trend params={"min_increase_pp": 12}
AC7  Enterprise AEs over plan-relative workload
     check=quota_vs_potential params={"dimension": "segment", "target_ratio_pct": 118, "band_pp": 6, "unit": "Enterprise"}
AC8  Effective capacity below headline headcount
     check=effective_capacity params={"target_pct": 82, "band_pp": 8, "unit": "Enterprise"}
AC9  Covering reps at 118% capacity-adjusted quota (depends_on: AC7, AC8)
     check=effective_capacity params={"target_pct": 118, "band_pp": 6, "unit": "Enterprise"}
AC10  Referential and value sanity
     check=data_sanity params={"max_discount_pct": 60}
